package algorithms.geometry;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class Geometry {
public record Point(double x,double y){}public record Pair(Point a,Point b,double distance){}public static double cross(Point o,Point a,Point b){return (a.x-o.x)*(b.y-o.y)-(a.y-o.y)*(b.x-o.x);}public static double distance(Point a,Point b){return Math.hypot(a.x-b.x,a.y-b.y);}private static List<Point> build(List<Point> a){List<Point> h=new ArrayList<>();for(Point p:a){while(h.size()>=2&&cross(h.get(h.size()-2),h.get(h.size()-1),p)<=0)h.remove(h.size()-1);h.add(p);}h.remove(h.size()-1);return h;}public static List<Point> convexHull(List<Point> p){List<Point> a=algorithms.sorting.MergeSort.mergeSort(p,Comparator.comparingDouble(Point::x).thenComparingDouble(Point::y));if(a.size()<3)return a;List<Point> o=build(a);Collections.reverse(a);o.addAll(build(a));return o;}public static double polygonArea(List<Point> p){double area=0;for(int i=0;i<p.size();i++){Point a=p.get(i),b=p.get((i+1)%p.size());area+=a.x*b.y-b.x*a.y;}return Math.abs(area)/2;}public static boolean pointInPolygon(Point p,List<Point> polygon){boolean inside=false;for(int i=0,j=polygon.size()-1;i<polygon.size();j=i++){Point a=polygon.get(i),b=polygon.get(j);if((a.y>p.y)!=(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)inside=!inside;}return inside;}private static boolean onSegment(Point p,Point q,Point r){return Math.min(p.x,r.x)<=q.x&&q.x<=Math.max(p.x,r.x)&&Math.min(p.y,r.y)<=q.y&&q.y<=Math.max(p.y,r.y);}public static boolean segmentsIntersect(Point p1,Point p2,Point q1,Point q2){double a=Math.signum(cross(p1,p2,q1)),b=Math.signum(cross(p1,p2,q2)),c=Math.signum(cross(q1,q2,p1)),d=Math.signum(cross(q1,q2,p2));return a!=b&&c!=d||a==0&&onSegment(p1,q1,p2)||b==0&&onSegment(p1,q2,p2)||c==0&&onSegment(q1,p1,q2)||d==0&&onSegment(q1,p2,q2);}public static Pair closestPair(List<Point> p){if(p.size()<2)return null;List<Point> a=algorithms.sorting.MergeSort.mergeSort(p,Comparator.comparingDouble(Point::x));Pair[] best={new Pair(a.get(0),a.get(1),distance(a.get(0),a.get(1)))};solve(a,0,a.size(),best);return best[0];}private static List<Point> solve(List<Point> a,int l,int r,Pair[] best){if(r-l<=3){for(int i=l;i<r;i++)for(int j=i+1;j<r;j++)update(a.get(i),a.get(j),best);return algorithms.sorting.MergeSort.mergeSort(a.subList(l,r),Comparator.comparingDouble(Point::y));}int m=(l+r)/2;double x=a.get(m).x;List<Point> left=solve(a,l,m,best),right=solve(a,m,r,best),merged=algorithms.sorting.MergeSort.merge(left,right,Comparator.comparingDouble(Point::y)),strip=new ArrayList<>();for(Point p:merged)if(Math.abs(p.x-x)<best[0].distance)strip.add(p);for(int i=0;i<strip.size();i++)for(int j=i+1;j<strip.size()&&strip.get(j).y-strip.get(i).y<best[0].distance;j++)update(strip.get(i),strip.get(j),best);return merged;}private static void update(Point a,Point b,Pair[] best){double d=distance(a,b);if(d<best[0].distance)best[0]=new Pair(a,b,d);}
}
